<script setup lang="ts">
import { computed, ref } from 'vue'
import { Aim, ArrowLeft, ArrowRight, Minus, Plus, Refresh } from '@element-plus/icons-vue'
import { ElButton, ElButtonGroup, ElCheckbox, ElCheckboxGroup, ElDatePicker, ElMessage, ElSegmented, ElTag } from 'element-plus'
import PageHeader from '../components/shell/PageHeader.vue'; import PrototypeStatePanel from '../components/shell/PrototypeStatePanel.vue'
import PlanDetailDialog from '../components/task-plan/PlanDetailDialog.vue'
import { ganttTasks, resolveTaskPlan } from '../mocks/taskPlans'; import type { PrototypeState } from '../types/prototype'; import type { TaskPlanRecord } from '../types/taskPlan'
const params=new URLSearchParams(location.search);const state=(params.get('state')||'normal') as PrototypeState;const date=ref('2026-09-10');const scale=ref('30m');const zoom=ref(100);const phases=ref(['上注','执行']);const types=ref(['成像','数传','软件']);const hours=Array.from({length:25},(_,i)=>String(i).padStart(2,'0')+':00');const satellites=['木铎1B','木铎1A'];const tasks=computed(()=>ganttTasks.filter(x=>phases.value.includes(x.phase)&&types.value.includes(x.lane)));const detailVisible=ref(false);const detailRecord=ref<TaskPlanRecord|null>(null);function move(day:number){date.value=day<0?'2026-09-09':day>0?'2026-09-11':'2026-09-10';ElMessage.info(`已切换至 ${date.value}`)}function changeZoom(delta:number){zoom.value=Math.min(140,Math.max(60,zoom.value+delta))}function statusClass(status:string){return status==='待发送'?'waiting':status==='执行失败'?'failed':'sent'}function openPlanDetail(planNo:string){detailRecord.value=resolveTaskPlan(planNo,'');detailVisible.value=true}
</script>
<template><section class="stage-four-page task-gantt-page"><PageHeader title="任务计划甘特图" description="卫星计划上注与执行时间轴"/><PrototypeStatePanel v-if="state!=='normal'" :state="state" subject="甘特图任务"/><template v-else><section class="gantt-toolbar"><div><el-button-group><el-button :icon="ArrowLeft" aria-label="前一天" @click="move(-1)"/><el-button @click="move(0)">今日</el-button><el-button :icon="ArrowRight" aria-label="后一天" @click="move(1)"/></el-button-group><el-date-picker v-model="date" type="date" value-format="YYYY-MM-DD"/></div><div class="gantt-controls"><label>刻度 <el-segmented v-model="scale" :options="['15m','30m','1h','2h']"/></label><label>阶段 <el-checkbox-group v-model="phases"><el-checkbox value="上注">上注</el-checkbox><el-checkbox value="执行">执行</el-checkbox></el-checkbox-group></label><label>类型 <el-checkbox-group v-model="types"><el-checkbox value="成像">成像</el-checkbox><el-checkbox value="数传">数传</el-checkbox><el-checkbox value="软件">软件</el-checkbox></el-checkbox-group></label><el-button-group><el-button :icon="Minus" aria-label="缩小" @click="changeZoom(-10)"/><el-button class="zoom-value">{{ zoom }}%</el-button><el-button :icon="Plus" aria-label="放大" @click="changeZoom(10)"/><el-button :icon="Refresh" aria-label="复位" @click="zoom=100"/></el-button-group></div></section><section class="gantt-legend"><span><i class="waiting"/>待发送</span><span><i class="sent"/>已发送</span><span><i class="uplinked"/>已上星</span><span><i class="success"/>执行成功</span><span><i class="failed"/>执行失败</span><b>北京时间（UTC+8）</b></section><div class="gantt-workbench"><aside class="gantt-labels"><div class="gantt-label-head">卫星 / 任务类型</div><template v-for="sat in satellites" :key="sat"><div class="satellite-label"><strong>{{ sat }}</strong><span>{{ sat==='木铎1B'?'2 成像 · 2 数传':'3 成像 · 1 数传' }}</span></div><div v-for="lane in ['成像','数传','软件']" :key="sat+lane" class="lane-label">{{ lane }}</div></template></aside><main class="gantt-canvas" :style="{minWidth:`${zoom*11}px`}"><div class="hour-axis"><span v-for="hour in hours" :key="hour">{{ hour }}</span></div><div class="current-line"><span><el-icon><Aim/></el-icon> 当前时刻</span></div><template v-for="sat in satellites" :key="sat"><div class="orbit-row"><span v-for="n in 8" :key="n">C{{ sat==='木铎1B'?242+n:244+n }}</span></div><div v-for="lane in ['成像','数传','软件']" :key="sat+lane" class="gantt-lane"><button v-for="task in tasks.filter(x=>x.satellite===sat&&x.lane===lane)" :key="task.id+task.phase" :class="['gantt-task',statusClass(task.status),task.phase==='上注'?'uplink':'execute']" :style="{left:`${task.left}%`,width:`${task.width}%`}" :title="`${task.id} · ${task.phase}`" @click="openPlanDetail(task.id)">{{ task.id }}<small>{{ task.phase }}</small></button></div></template></main><aside class="gantt-side"><article v-for="sat in satellites" :key="sat"><h3>{{ sat }}</h3><div><span>成像<b>{{ sat==='木铎1B'?2:3 }}</b></span><span>数传<b>{{ sat==='木铎1B'?2:1 }}</b></span><span>软件<b>0</b></span></div><dl><div><dt>已到时 / 未到时</dt><dd>0 / 4</dd></div><div><dt>轨道高度</dt><dd>530 km</dd></div><div><dt>类型</dt><dd>SSO</dd></div><div><dt>周期</dt><dd>{{ sat==='木铎1B'?'95.5':'95.4' }} min</dd></div></dl></article><article class="gantt-total"><h3>执行状态</h3><p><el-tag type="warning">待发送 3</el-tag><el-tag>已发送 5</el-tag><el-tag type="info">已上星 0</el-tag><el-tag type="success">执行成功 0</el-tag><el-tag type="danger">执行失败 0</el-tag></p><strong>任务计划 <b>8</b></strong></article></aside></div></template><PlanDetailDialog v-model:visible="detailVisible" :record="detailRecord"/></section></template>
